-- Conteúdo alinhado ao doc "Sistema Arcano" em 2026-11-13 (decisões do Mestre na conversa).

-- ===== Feitiços =====
update spells set description = 'Liberação instintiva de mana bruta no exato instante do ataque físico, dobrando o dano como mágico e aplicando +2d6 de dano mágico puro, também ignorando armadura. Qualquer humano sob estresse extremo pode manifestá-la, mesmo sem treino mágico. Essa liberação foi a descoberta fundamental para os humanos dominarem os profanos e druídas, raças contra as quais os anões não tinham um método muito efetivo.',
  restrictions = 'Liberação passiva: todo personagem nasce com Ruptura, exceto anões (que só a usam por meio de itens, como a Espada Carmesim).',
  notes = '' where name = 'Ruptura' and campaign_id is null;

update spells set description = 'O conjurador imprime sua assinatura de mana em um objeto inanimado, criando um vínculo que pode invocar o retorno do objeto. A canalização por objeto custa 60 de mana e cada chamado custa 10 de mana, com alcance de 10m. Caso Lealdade seja usada duas vezes no mesmo objeto, ela se torna Lealdade Universal: qualquer um pode usar Chamado nesse objeto.'
where name = 'Lealdade' and campaign_id is null;

update spells set description = 'Invoca o retorno de um objeto com o qual o conjurador tem Lealdade, ou de um objeto com Lealdade Universal. Cada chamado custa 10 de mana, com alcance de 10m.',
  restrictions = 'Só pode ser usado quando o conjurador tem Lealdade com o objeto, ou quando o objeto tem Lealdade Universal (Lealdade usada duas vezes nele).',
  notes = '' where name = 'Chamado' and campaign_id is null;

-- ===== Itens =====
update items set aa_multiplier = 4,
  notes = 'Ambiguidades registradas: (1) "o ser mais fraco possível da raça" não tem números definidos — o Mestre define os valores da maldição; (2) o sacrifício é contado por empunhadura e zera ao largar.'
where name = 'Filho do Sol' and campaign_id is null;

update items set damage_dice_count = 1, damage_dice_sides = 6, aa_multiplier = 3 where name = 'Espada Carmesim' and campaign_id is null;

update items set description = replace(description, E'A Torre - A estrutura não vai aguentar o impacto.\n',
  E'A Torre - A estrutura não vai aguentar o impacto.\nA Estrela - O que parece perdido ainda pode ser restaurado, se você não abandonar o caminho.\n')
where name = 'Baralho Arcano' and campaign_id is null and description not like '%A Estrela -%';

-- ===== Criaturas: periculosidade escrita no texto do doc =====
update creatures set periculosidade = 1 where campaign_id is null and name in ('Gira-Gira', 'Oraqui-Oralá', 'Furanzão');
update creatures set periculosidade = 4 where campaign_id is null and name = 'Erumpente';

-- ===== Criaturas: textos reescritos para Arkhavel (sem referências de fora do mundo) =====
update creatures set description = v.d from (values
('Claberto', $T$Criatura arbórea que lembra uma cruza de mico com sapo. Pele lisa e malhada de verde, mãos e pés palmados, braços e pernas longos e flexíveis que permitem balanço entre galhos com agilidade de primata. Cabeça com pequenos chifres e boca larga cheia de dentes afiados como navalha. Come principalmente pequenos lagartos e aves. Sua característica mais notável é uma pústula enorme no meio da testa que fica vermelha e faísca quando detecta perigo. Vilarejos afastados da Capital costumavam mantê-los nos pomares como alarme contra profanos. A guarda proibiu a prática quando ficou óbvio que uma árvore cheia de pústulas brilhando à noite atraía mais profanos do que afastava — principalmente no inverno, quando as pústulas eram a única luz da estrada.$T$),
('Gira-Gira', $T$Inseto das florestas temperadas de Arkhavel, com pouco mais de um centímetro, azul-safira intenso. Sua velocidade é tão grande que raramente é percebido antes de picar. As asas saem do topo da cabeça e giram em alta velocidade durante o voo; na extremidade oposta há um ferrão longo e fino. A picada causa tontura seguida de levitação. O efeito é temporário em doses normais — em doses altas, a flutuação pode durar dias. Em casos de reação severa, pode se tornar permanente. Gerações de jovens dos vilarejos têm tentado deliberadamente ser picados por gira-giras para flutuar acima das copas. Esse fato diz tudo o que precisa ser dito sobre o julgamento dos jovens de Arkhavel. Em jogo: periculosidade I. O perigo não vem do inseto — vem do jogador impulsivo que decide provocar um. A mecânica de levitação involuntária por dias cria situações que o mestre não precisa planejar; elas se criam sozinhas.$T$),
('Oraqui-Oralá', $T$Ave roliça, de penas fofas, incapaz de voo, que desaparece em nuvem de penas e reaparece em outro lugar quando ameaçada. Os caçadores da Capital acreditaram tê-la levado à extinção há gerações, e a Escola de Caça ainda ensina a história como exemplo do preço da caça sem controle — um equívoco útil demais para que alguém se dê ao trabalho de corrigir. Em jogo: periculosidade I. O animal em si é inofensivo e impossível de capturar por meios físicos. O momento de um guarda da Capital entrar em colapso ao ver uma oraqui-oralá viva diante de si vale qualquer encontro mais elaborado.$T$),
('Tronquilho', $T$Criatura guardiã de árvores encontrada nas Florestas Druídicas do oeste e na grande floresta do sudeste. Pequeno — no máximo vinte centímetros — e composto aparentemente de tronco e gravetos com dois olhinhos castanhos. Pacífico e extremamente tímido em condições normais. Se a árvore em que vive for ameaçada, fura os olhos do responsável com dedos longos e afiados sem hesitação. Pode ser acalmado com bichos-de-conta por tempo suficiente para retirar madeira da árvore — material cobiçado por artesãos de cajados e pelos santuários druídicos. Em jogo: aliado de bolso literalmente. Cabe no bolso, não reclama, detecta ameaças à árvore com precisão, e o custo de manutenção é bichos-de-conta. O problema aparece quando o grupo esquece que o tronquilho está no bolso durante uma negociação delicada e alguém menciona lenha.$T$),
('Amasso', $T$Pequeno felino com pelo pintado ou malhado, orelhas grandes e rabo igual ao de leão. Inteligente, independente e às vezes agressivo — mas quando se afeiçoa a alguém, torna-se aliado absolutamente leal. Detecta pessoas suspeitas ou perigosas com precisão consistente — inclusive profanos disfarçados — e pode guiar o dono de volta para casa mesmo em território desconhecido. Cruza com os gatos comuns dos vilarejos. Em jogo: detector passivo de intenções. O amasso rosna — e agora o grupo tem que decidir se confia mais no gato ou no NPC de aparência completamente inofensiva. Raramente erra. O mestre pode usá-lo como dica sutil ou como fonte de paranoia constante dependendo de como jogar.$T$),
('Erumpente', $T$Animal cinzento de até uma tonelada, parecido com um rinoceronte, que vive nos Campos e Pradarias ao redor da Capital. Couro que repele a maioria dos feitiços e maldições. Chifre afiado que perfura qualquer coisa, de pele a metal, contendo uma secreção que faz o alvo atingido explodir — e o próprio erumpente explode se o chifre perfurar algo de mau jeito, o que o torna perigoso até para si mesmo. Não ataca a não ser quando provocado pela dor — o problema é que "provocado" inclui qualquer estímulo inesperado. Os machos frequentemente se explodem mutuamente durante a estação de acasalamento, o que limita naturalmente a população. Em jogo: periculosidade IV. O couro que repele feitiços obriga confronto físico ou estratégias indiretas. O chifre que explode o alvo transforma qualquer erro de posicionamento em consequência permanente. Usar como obstáculo — algo que o grupo precisa contornar sem provocar — é mais interessante do que confronto direto.$T$),
('Pufoso', $T$Criatura esférica coberta de pelos macios cor de amarelo. Não se importa de ser afagado, jogado, carregado ou ignorado. Emite zumbido surdo quando satisfeito. A intervalos, estende uma língua longa, fina e rosada que serpeia pela casa em busca de comida — come qualquer coisa, desde sobras até aranhas, com preferência especial por enfiar a língua no nariz de quem dorme para comer o que encontrar. Essa tendência o tornou o favorito das crianças dos vilarejos por gerações. Em jogo: mascote de campanha ideal. Cria afeto nos jogadores sem fazer nada útil. Há recrutas da Escola de Guarda que o usam como alvo de treino de arremesso — o que diz bastante sobre a versatilidade do animal como entretenimento de baixo custo.$T$),
('Gnomo', $T$Praga comum de hortas e jardins em todos os vilarejos de Arkhavel, o gnomo tem cerca de trinta centímetros de altura, cabeça desproporcionalmente grande e dura e pés ossudos. Não é perigoso — é inconveniente. Infesta jardins, destrói canteiros e resiste a remoção com uma determinação que beira o heroísmo. O método padrão de controle é girar o bicho no alto até a tontura e arremessá-lo por cima do muro. Ele volta. Sempre volta. Em jogo: periculosidade I. Encontros com gnomos são quase sempre involuntários — o grupo está fazendo outra coisa e os gnomos estão atrapalhando. Competição entre jogadores para ver quem arremessa mais longe é evento recorrente em qualquer jardim de NPC importante. Um furanzão resolve o problema mais rápido, mas com dano colateral considerável.$T$),
('Pocotó', $T$Guardião de cavalos encontrado nos Campos e Pradarias ao redor da Capital e nas estrebarias dos vilarejos. Sessenta centímetros de altura, coberto de pelagem comprida, nariz excepcionalmente grande e patas de casco fendido. Existe exclusivamente para proteger cavalos. Desconfia de humanos e foge quando se aproximam. Se encontrado escondido no feno ou no meio de uma manada, geralmente significa que os cavalos estão sob alguma ameaça que o grupo ainda não percebeu. Em jogo: NPC animal involuntário. O pocotó não quer ser encontrado, não quer ser útil e não quer interagir com ninguém. O fato de estar agitado é informação. Ganhar sua confiança é uma missão inteira por si só, e a recompensa é um aliado que protege cavalos com devoção absoluta — o que é mais útil do que parece em campanhas de longa viagem.$T$),
('Grindylow', $T$Profano aquático de chifres e pele verde-clara que habita os Grandes Lagos e os Pântanos e Brejos de Arkhavel. Alimenta-se de pequenos peixes. Agressivo com qualquer um que entre na água, com dedos muito longos que têm força considerável mas são facilmente quebráveis. Sereias e tritões conseguem domesticá-los. Em jogo: encontro subaquático padrão de baixa periculosidade — II no máximo. O perigo é proporcional a quanto os jogadores subestimam o ambiente aquático. Dedos quebrando é a solução mecânica; o problema é alcançá-los debaixo d'água sem entrar em pânico.$T$),
('Pogrebin', $T$Profano das regiões frias da Taiga, com menos de trinta centímetros, corpo peludo e cabeça enorme, cinzenta e lisa. Quando encolhido, parece uma pedra redonda e brilhante. É atraído por humanos e gosta de segui-los andando à sombra, abaixando-se rapidamente quando o alvo se vira. Se um humano permitir que o pogrebin o siga por horas, começa a sentir futilidade crescente que evolui para letargia e desespero. Quando a vítima para de andar e cai de joelhos para chorar a inutilidade de tudo, o pogrebin salta sobre ela e tenta devorá-la. É facilmente repelido com feitiços simples ou com sal. Chutá-lo para longe também é eficaz. Em jogo: periculosidade II. O perigo não é o pogrebin — é o jogador que não percebe que está sendo seguido por horas e de repente sente uma tristeza inexplicável e avassaladora no meio de uma missão importante. O mestre pode usar como ferramenta de tensão cômica ou como diagnóstico de quanto os jogadores prestam atenção ao ambiente.$T$),
('Hipogrifo', $T$Cabeça de águia enorme sobre corpo de cavalo, comum nas Montanhas Alpinas e nas bordas da Taiga. Domesticável, mas exclusivamente por quem conhece o ritual de aproximação: contato visual mantido, reverência lenta, aguardar resposta. Um hipogrifo que retribui a reverência pode ser aproximado. Um hipogrifo que não retribui vai atacar. Não há estado intermediário. Come insetos, aves e pequenos mamíferos. Constrói ninho no chão e choca um único ovo em vinte e quatro horas. Em jogo: periculosidade III — grave se ignorado o protocolo, manejável com conhecimento. O encontro com um hipogrifo é um teste de informação antes de ser um teste de combate. Jogadores que tentarem forçar a aproximação sem reverência descobrirão que quatro metros de águia-cavalo atacando é mais rápido do que parece.$T$),
('Mortalha-Viva', $T$Manto negro de mana condensada, pouco mais de um centímetro de espessura em repouso, mais espesso após alimentação recente. Rasteja pelo chão durante a noite buscando presas adormecidas. Após sufocar a vítima, digere no local e sai da habitação levemente mais espessa, sem deixar rastro da criatura ou da vítima. O único recurso conhecido eficaz contra ela é o fogo, a aversão de todo profano. Ataques físicos e feitiços convencionais não produzem efeito relevante. Em jogo: periculosidade IV em condições de surpresa, II com preparação. O perigo é quase exclusivamente informacional — quem sabe o que está enfrentando e tem fogo à mão resolve o encontro imediatamente. Quem não sabe, provavelmente não acorda.$T$),
('Cavalo-do-Lago', $T$Profano aquático que assume preferencialmente a forma de um cavalo com crina de folhas de taboa. Após atrair um cavaleiro, mergulha direto ao fundo e devora a vítima. O maior espécime de Arkhavel vive no Lago das Brumas ao norte e prefere a forma de serpente d'água — foi observado se transformando em lontra ao perceber guardas da Escola de Caça e voltando à forma de serpente quando eles foram embora. O único método de controle conhecido é trançar sal nas rédeas, aproveitando a aversão de todo profano ao sal. Em jogo: periculosidade IV. Encontro de informação antes de ser encontro de combate — quem não sabe o que é o cavalo bonito à beira do lago está a uma ação impulsiva de um afogamento garantido. O espécime do Lago das Brumas especificamente é avançado demais para confronto direto e funciona melhor como presença constante e problema em aberto.$T$),
('Acromântula', $T$Aranha monstruosa de oito olhos com envergadura de pernas de até quatro metros e meio, dotada de fala humana. Há uma colônia não oficialmente confirmada nas florestas ao norte de Arkhavel, na Taiga. Carnívora, prefere presas grandes. A fêmea pode depositar até cem ovos por postura. O comércio de seus ovos é proibido pela Capital. Inteligência quase humana — o que significa que negocia, engana e planeja. Não é treinável por nenhum método conhecido. Em jogo: periculosidade V em grupo, IV isolada. O perigo real não é um indivíduo — é uma colônia. O mestre que colocar o grupo em contato com uma colônia de acromântulas sem preparação adequada está cometendo homicídio narrativo. A capacidade de fala torna possível negociação, o que é ao mesmo tempo a oportunidade e a armadilha: acromântulas negociam quando é conveniente para elas.$T$),
('Basilisco', $T$Profano que assume a forma de uma cobra verde de até quinze metros, nascido de experimentos proibidos de um conjurador da Capital com ovos de galinha chocados por sapos. O macho tem pluma vermelha. As presas são excepcionalmente venenosas. O olhar mata instantaneamente qualquer ser que estabeleça contato visual direto — sem dado, sem teste, sem exceção. Contato indireto, via reflexo em água ou superfície polida, causa inconsciência. Lâmias exercem algum grau de controle instável sobre a criatura. Sua criação é proibida pela Família Vetra desde a fundação do reino. Em jogo: periculosidade V absoluta. Não há encontro justo com um basilisco para a maioria dos grupos. A única margem de sobrevivência conhecida é o reflexo — e explorar esse detalhe requer que o grupo saiba o que está enfrentando antes de entrar na sala. Chefe de masmorra que exige preparação, informação e execução coordenada.$T$),
('Quimera', $T$Profano com cabeça de leão, corpo de bode e rabo de dragão. Mana instável que se manifesta como comportamento errático e destrutivo. Cada parte do corpo age com grau de autonomia próprio, o que torna os movimentos imprevisíveis mesmo para quem conhece a criatura. Sopra fogo. O único registro de abate é de um caçador anônimo da Escola de Caça que morreu de exaustão logo após. Em jogo: periculosidade V. A imprevisibilidade de ataque de múltiplos vetores simultâneos é o perigo principal — não há posicionamento seguro contra uma criatura cujo rabo dispara independente de onde a cabeça está olhando.$T$)
) as v(n, d) where creatures.name = v.n and creatures.campaign_id is null;

-- ===== Lacunas de regra: status conforme o doc atual =====
update rule_gaps set status = 'resolvida' where campaign_id is null and topic in
  ('Feitos Mágicos: Profano', 'Forjado e conjuração', 'Calendário: 22 dias × 23 dias', 'Força de Massa no nível 1', 'Profano e dano físico', 'Bestiário');
update rule_gaps set description = 'O doc atual diz apenas: "resultado abaixo de 10 deturpa os efeitos e aumenta o custo (máx. 2×)". O site aplica a tabela antiga (9 → ×1,2 … 1 → ×2,0). Confirme se a tabela continua valendo.'
where campaign_id is null and topic = 'Feitos Mágicos: frase × tabela';
update rule_gaps set description = 'Os 16 itens arcanos ainda não têm efeitos automáticos na ficha (só o Filho do Sol). Ver docs/RELATORIO_DOC_X_SISTEMA.md.'
where campaign_id is null and topic = 'Itens arcanos: efeitos mecânicos';
